// Tipos de datos de la API
export interface User {
  id: number;
  name: string;
  email: string;
  created_at: string;
  updated_at?: string;
}

export interface Category {
  id: number;
  name: string;
  description: string;
  created_at: string;
  product_count?: number;
}

export interface Product {
  id: number;
  name: string;
  description: string;
  price: number;
  stock: number;
  category_id: number;
  category?: string;
  created_at: string;
  updated_at?: string;
}

export interface OrderItem {
  id: number;
  product_id: number;
  product_name?: string;
  quantity: number;
  price: number;
  subtotal: number;
}

export interface Order {
  id: number;
  user_id: number;
  user_name?: string;
  total: number;
  status: 'pending' | 'completed' | 'cancelled';
  items: OrderItem[];
  created_at: string;
  updated_at?: string;
}

// Tipos para formularios
export interface CreateUserData {
  name: string;
  email: string;
}

export interface CreateProductData {
  name: string;
  price: number;
  stock: number;
  category_id: number;
  description: string;
}

export interface CreateCategoryData {
  name: string;
  description: string;
}

export interface CreateOrderData {
  user_id: number;
  items: {
    product_id: number;
    quantity: number;
  }[];
}

// Tipos para respuestas de la API
export interface ApiResponse<T> {
  success: boolean;
  data: T;
  message?: string;
  error?: string;
