                'sku': product.sku,
                'stock': product.stock,
                'restock_value': float(product.cost) * (threshold - product.stock) if product.cost else 0
            }
            for product in products
        ]

        return success_response(data=result, count=len(result))
    except Exception as e:
        return error_response(f'Error al obtener productos con stock bajo: {str(e)}', 500)

